import subprocess, os, pathlib, shutil
exe="./executable"
def run(args):
    p=subprocess.run([exe]+args, capture_output=True, text=True, timeout=3)
    return p.stdout

def get_sql(filters):
    args=["-N","-n","-q"]
    for f in filters:
        args+=["-c", f]
    args+=["-c",";SELECT log_body FROM syslog_log","-c",":write-csv-to -","/tmp/syslog.log"]
    return run(args)

def get_set_sql(filters):
    out=get_sql(filters)
    lines=out.strip().splitlines()
    # skip header
    if len(lines)<=1:
        return set()
    return set(lines[1:])

# Test model: enabled filters logic: first occurrence enabled, rest disabled (as we hypothesized earlier) but with evaluation: if any in enabled, only show lines matching any in AND not matching any out; else only show not matching any out.

def eval_model(filters):
    # filters list of (type,pattern) like ":filter-in error" string? We'll parse
    parsed=[]
    for cmd in filters:
        # cmd like ":filter-in error"
        parts=cmd.split()
        # first part ":filter-in" or ":filter-out"
        typ=parts[0].split("-")[1] # "in" or "out"
        pat=" ".join(parts[1:])
        parsed.append((typ,pat))
    # First occurrence enabled
    seen=set()
    enabled=[]
    for typ,pat in parsed:
        if pat not in seen:
            enabled.append((typ,pat))
            seen.add(pat)
        else:
            # disabled
            pass
    in_pats=[p for t,p in enabled if t=="in"]
    out_pats=[p for t,p in enabled if t=="out"]
    def shown(line):
        if in_pats:
            if not any(p.lower() in line.lower() for p in in_pats):
                return False
            if any(p.lower() in line.lower() for p in out_pats):
                return False
            return True
        else:
            return not any(p.lower() in line.lower() for p in out_pats)
    res=set()
    for lt in ["error happened","warning happened","info happened"]:
        if shown(lt):
            res.add(lt)
    return res

tests=[
[":filter-in error"],
[":filter-out error"],
[":filter-in error",":filter-out error"],
[":filter-out error",":filter-in error"],
[":filter-in error",":filter-in warning"],
[":filter-in warning",":filter-in error"],
[":filter-out error",":filter-out warning"],
[":filter-in error",":filter-out warning"],
[":filter-out error",":filter-in warning"],
[":filter-in error",":filter-in warning",":filter-out error"],
