[":filter-in error",":filter-in nomatch"],
[":filter-in nomatch",":filter-in error"],
[":filter-in error",":filter-out nomatch"],
]
for t in tests:
    obs=get_set_sql(t)
    model=eval_model(t)
    print(t, "obs", obs, "model", model, "match", obs==model)
