            f_min=min(times); f_max=max(times)
        else:
            c,mt=get_ft_range(fp)
            f_min=mt; f_max=mt
        is_out=False
        if since_dt and f_max and f_max < since_dt: is_out=True
        if until_dt and f_min and f_min > until_dt: is_out=True
        if is_out:
            c,mt=get_ft_range(fp)
            out_of_range.append((fp,c,mt))
        else:
            filtered_per=filter_time(per, since_dt, until_dt)
            filtered_entries.extend(filtered_per)

    shell_stdin=[e for e in all_entries if e.get('from_shell') or e.get('from_stdin')]
    filtered_entries.extend(filter_time(shell_stdin, since_dt, until_dt))

    if out_of_range and not filtered_entries and not ordered_cmd_ops:
        fp,c,mt=out_of_range[0]
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)
        sys.exit(1)
    for fp,c,mt in out_of_range:
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)

    def skey(e):
        lt=e.get('log_time')
        if lt:
            return (lt, e.get('log_line',0))
        else:
            return (datetime.datetime.min.replace(tzinfo=timezone.utc), e.get('log_line',0))
    filtered_entries.sort(key=skey)

    final_cmds=[]
    for typ,val in ordered_cmd_ops:
        if typ=='c':
            final_cmds.append(val)
        elif typ=='f':
            if val=='-':
                if stdin_cmd_data:
                    for line in stdin_cmd_data.splitlines():
                        if line.strip():
