                sys.exit(0)
            if op=="list":
                if op_args and op_args[0] in ("-h","--help"):
                    sys.stdout.write("list the log format regular expression linked to entries on regex101.com\nUsage: {prog} regex101 list [OPTIONS]\n\nOptions:\n  -h,--help                   Print this help message and exit\n\nVersion: lnav 0.14.0-8ad2d43\n".format(prog=prog))
