            elif op=="import":
                if op_args and op_args[0] in ("-h","--help"):
                    sys.stdout.write("create a new format from a regular expression on regex101.com\nUsage: {prog} regex101 import [OPTIONS] [url] [name] [regex-name]\n\nPositionals:\n  url TEXT                    The regex101.com url to construct a log format from\n  name TEXT                   The name for the log format\n  regex-name TEXT             The name for the new regex\n\nOptions:\n  -h,--help                   Print this help message and exit\n\nVersion: lnav 0.14.0-8ad2d43\n".format(prog=prog))
