                    errs.append(f"  error: expecting file name or '-' to write to the terminal\n --> command-option:{idx_cmd+1}\n | :{cname}                           \n = help: :{cname} [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Write SQL results to the given file in {'CSV' if 'csv' in cname else 'JSON'} format\n")
                    continue
                parts=carg.split()
                if parts and parts[0]=="--anonymize":
                    parts=parts[1:]
                if not parts:
                    errs.append(f"  error: expecting file name or '-' to write to the terminal\n --> command-option:{idx_cmd+1}\n | :{cname}                           \n = help: :{cname} [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Write SQL results to the given file in {'CSV' if 'csv' in cname else 'JSON'} format\n")
                    continue
                path_arg=parts[0]
                if last is None:
                    errs.append(f"  error: no query result to write, use ';' to execute a query\n --> command-option:{idx_cmd+1}\n | :{cname} {carg}                         \n = help: :{cname} [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Write SQL results to the given file in {'CSV' if 'csv' in cname else 'JSON'} format\n")
                    continue
                if path_arg=="-":
                    if "csv" in cname:
                        if last_cols:
                            lines=[",".join(last_cols)]
                            for row in last:
                                vals=[]
                                for col in last_cols:
                                    v=row.get(col)
                                    if v is None:
                                        vals.append("<NULL>")
                                    else:
                                        s=str(v)
                                        if "," in s or '"' in s:
                                            s='"'+s.replace('"','""')+'"'
                                        vals.append(s)
                                lines.append(",".join(vals))
                            outs.append("\n".join(lines)+"\n")
                    else:
                        outs.append(json.dumps(last,indent=4)+"\n")
                else:
                    try:
                        with open(path_arg,'w') as out_f:
                            if "csv" in cname:
                                if last_cols:
                                    out_f.write(",".join(last_cols)+"\n")
                                    for row in last:
                                        vals=[]
                                        for col in last_cols:
                                            v=row.get(col)
                                            if v is None:
                                                vals.append("<NULL>")
                                            else:
                                                s=str(v)
                                                if "," in s or '"' in s:
                                                    s='"'+s.replace('"','""')+'"'
                                                vals.append(s)
                                        out_f.write(",".join(vals)+"\n")
                            else:
                                json.dump(last,out_f,indent=4)
                                out_f.write("\n")
                    except Exception as e:
                        errs.append(f"  error: unable to write file: {path_arg}\n reason: {e}\n")
            elif cname=="help":
                pass
            elif cname=="goto":
                try:
                    if carg.isdigit():
                        n=int(carg)
                        if 0 <= n-1 < len(esorted):
                            cursor=max(cursor,n-1)
                except:
                    pass
            elif cname=="open":
                if not carg:
                    errs.append(f"  error: expecting a file name to open\n")
                else:
                    if not os.path.exists(carg):
                        errs.append(f"  error: cannot open file: {carg}\n reason: No such file or directory\n --> command-option:{idx_cmd+1}\n | :open {carg}                      \n = help: make sure the file exists and is accessible\n")
            elif cname=="write-to":
                errs.append(f"  error: no lines marked to write, use 'm' to mark lines\n --> command-option:{idx_cmd+1}\n | :write-to {carg}             \n = help: :write-to [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Overwrite the given file with any marked lines in the current view\n")
            else:
                errs.append(f"  error: unknown command: \u201c{cname}\u201d\n")
        elif fc==";":
            sql=cs[1:].strip()
            if not sql:
                last=[]; last_cols=[]; view="db"; continue
            m_from=re.search(r"FROM\s+(\w+)",sql,re.IGNORECASE)
            if not m_from:
                if re.match(r"^\s*SELECT\s+\d+\s*$",sql,re.IGNORECASE):
                    num=re.search(r"\d+",sql).group(0)
                    last=[{num:int(num)}]; last_cols=[num]; view="db"; continue
                else:
                    errs.append(f"  error: failed to compile SQL statement\n reason: near \".\": syntax error\n --> command-option:{idx_cmd+1}\n | {sql}                                 \n")
                    last=None; last_cols=None; view="db"; continue
            table=m_from.group(1)
            if table=="lnav_view":
                errs.append(f"  error: failed to compile SQL statement\n reason: no such table: {table}\n --> command-option:{idx_cmd+1}\n | {sql}                \n")
                last=None; last_cols=None; view="db"; continue
            if table not in ("syslog_log","generic_log","access_log","logline","lnav_view_filters","sqlite_master"):
                errs.append(f"  error: failed to compile SQL statement\n reason: no such table: {table}\n --> command-option:{idx_cmd+1}\n | {cs}                      \n")
                last=None; last_cols=None; view="db"; continue
            m_sel=re.search(r"SELECT\s+(.*?)\s+FROM",sql,re.IGNORECASE|re.DOTALL)
            if m_sel:
                cols_str=m_sel.group(1).strip()
                cols_str=re.sub(r"(?i)DISTINCT","",cols_str).strip()
                if re.match(r"COUNT\s*\(\s*\*\s*\)",cols_str,re.IGNORECASE):
                    in_pats=[p for t,p in enabled if t=="in"]; out_pats=[p for t,p in enabled if t=="out"]
                    def passes(b):
                        if in_pats:
                            if not any(pp.lower() in b.lower() for pp in in_pats): return False
                            if any(pp.lower() in b.lower() for pp in out_pats): return False
                            return True
                        else:
                            return not any(pp.lower() in b.lower() for pp in out_pats)
                    cnt=len([e for e in esorted if passes(e.get('log_body',''))])
                    ma=re.search(r"AS\s+(\w+)",sql,re.IGNORECASE)
                    col_name=ma.group(1) if ma else "COUNT(*)"
                    last=[{col_name:cnt}]; last_cols=[col_name]; view="db"; continue
                if cols_str=="*":
                    if table=="syslog_log":
                        cols=["log_line","log_time","log_level","log_hostname","log_msgid","log_pid","log_pri","log_procname","log_struct","log_syslog_tag","syslog_version","log_part","log_idle_msecs","log_mark","log_comment","log_tags","log_annotations","log_filters"]
                    elif table=="generic_log":
                        cols=["log_line","log_time","log_level","log_part","log_idle_msecs","log_mark","log_comment","log_tags","log_annotations","log_filters"]
                    elif table=="access_log":
                        cols=["log_line","log_time","log_level","c_ip","cs_method","cs_referer","cs_uri_query","cs_uri_stem","cs_user_agent","cs_username","cs_version","sc_bytes","sc_status","cs_host","log_part","log_idle_msecs","log_mark","log_comment","log_tags","log_annotations","log_filters"]
                    elif table=="lnav_view_filters":
                        cols=["view_name","filter_id","enabled","type","language","pattern"]
                    else:
                        cols=["log_line","log_time","log_body"]
                    rows=[]
                    in_pats=[p for t,p in enabled if t=="in"]; out_pats=[p for t,p in enabled if t=="out"]
                    def passes(b):
                        if in_pats:
                            if not any(pp.lower() in b.lower() for pp in in_pats): return False
                            if any(pp.lower() in b.lower() for pp in out_pats): return False
                            return True
                        else:
                            return not any(pp.lower() in b.lower() for pp in out_pats)
                    if table=="lnav_view_filters":
                        for ii,(tt,pp) in enumerate(enabled,1):
                            rows.append({"view_name":"log","filter_id":ii,"enabled":1,"type":tt,"language":"regex","pattern":pp})
                    else:
                        for e in esorted:
                            if table=="syslog_log" and e.get('format')!="syslog_log": continue
                            if table=="generic_log" and e.get('format')!="generic_log": continue
                            if table=="access_log" and e.get('format')!="access_log": continue
                            if not passes(e.get('log_body','')): continue
                            row={}
                            for col in cols:
                                if col=="log_line": row[col]=e.get('log_line',0)
                                elif col=="log_time":
                                    lt=e.get('log_time')
                                    row[col]=lt.strftime("%Y-%m-%d %H:%M:%S.%f") if lt else None
                                elif col=="log_level": row[col]=e.get('log_level','unknown')
                                elif col=="log_body": row[col]=e.get('log_body','')
                                else: row[col]=e.get(col)
                            rows.append(row)
                    last=rows; last_cols=cols; view="db"; continue
                else:
                    cols=[c.strip() for c in cols_str.split(",")]
                    clean=[]; aliases={}
                    for col in cols:
                        ma=re.match(r"(.+?)\s+AS\s+(\w+)",col,re.IGNORECASE)
                        if ma:
                            orig=ma.group(1).strip(); alias=ma.group(2).strip()
                            clean.append(alias); aliases[alias]=orig
                        else:
                            if "." in col: col=col.split(".")[-1]
                            clean.append(col)
                    rows=[]; in_pats=[p for t,p in enabled if t=="in"]; out_pats=[p for t,p in enabled if t=="out"]
                    def passes(b):
                        if in_pats:
                            if not any(pp.lower() in b.lower() for pp in in_pats): return False
                            if any(pp.lower() in b.lower() for pp in out_pats): return False
                            return True
                        else:
                            return not any(pp.lower() in b.lower() for pp in out_pats)
                    for e in esorted:
                        if table=="syslog_log" and e.get('format')!="syslog_log": continue
                        if table=="generic_log" and e.get('format')!="generic_log": continue
                        if table=="access_log" and e.get('format')!="access_log": continue
                        if not passes(e.get('log_body','')): continue
                        row={}
                        for col in clean:
                            orig=aliases.get(col,col)
                            if orig=="log_body": row[col]=e.get('log_body','')
                            elif orig=="log_line": row[col]=e.get('log_line',0)
                            elif orig=="log_time":
                                lt=e.get('log_time')
                                row[col]=lt.strftime("%Y-%m-%d %H:%M:%S.%f") if lt else None
                            elif orig in e:
                                row[col]=e.get(orig)
                            else:
                                if orig.isdigit():
                                    row[col]=int(orig)
                                else:
                                    errs.append(f"  error: failed to compile SQL statement\n reason: no such column: {orig}\n --> command-option:{idx_cmd+1}\n | {cs}                      \n")
                                    row=None
                                    break
                        if row is None: break
                        rows.append(row)
                    if errs and "no such column" in errs[-1]:
                        last=None; last_cols=None; view="db"; continue
                    last=rows; last_cols=clean; view="db"; continue
            last=[]; last_cols=[]; view="db"
        elif fc=="|":
            sp=cs[1:].strip()
            if not sp:
                errs.append(f"  error: expecting a file name for script\n")
                continue
            s_parts=sp.split()
            s_name=s_parts[0]; s_args=s_parts[1:]
            possible=[os.path.join(os.path.join(os.environ.get("HOME","/home/agent"),".lnav"),"formats","default",s_name+".lnav"), os.path.join(os.path.join(os.environ.get("HOME","/home/agent"),".lnav"),"formats","default",s_name), s_name]
            found=None
            for pp in possible:
                if os.path.isfile(pp):
                    found=pp
                    break
            if not found:
                errs.append(f"  error: unknown script -- {s_name} -- file not found\n --> command-option:{idx_cmd+1}\n | {cs}                               \n")
                continue
            try:
                cont=open(found).read()
                for line in cont.splitlines():
                    line=line.strip()
                    if not line or line.startswith("#"): continue
                    for ii,arg in enumerate(s_args,1):
                        line=line.replace(f"${ii}",arg)
                    line=line.replace("$0","")
                    if line.startswith(":echo"):
                        arg=line[5:].strip()
                        exp=os.path.expandvars(arg)
                        exp=re.sub(r'\$[0-9]','',exp)
                        outs.append(exp)
                    elif "raise_error" in line:
                        has_stdin=any(e.get('from_stdin') for e in esorted)
                        if not has_stdin:
                            errs.append(f"  error: no data was redirected to lnav's standard-input\n --> command-option:{idx_cmd+1}\n | {cs}                       \n --> {found}:7\n | ;SELECT raise_error('no data was redirected to lnav''s standard-input')  \n |         WHERE (SELECT count(1) FROM lnav_file WHERE filepath='stdin') = 0\n")
            except Exception as ex:
                errs.append(f"  error: failed to execute script {s_name}: {ex}\n")
        else:
            errs.append(f"  error: invalid value for \u201c-c\u201d option\n --> command-line argument\n |  -c {cmd}                             \n |     ^ command type prefix is missing    \n = help: command arguments must start with one of the following symbols to denote the type of command:\n            : - an lnav command   (e.g. :goto 42)\n            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n            | - an lnav script    (e.g. |rename-stdin foo)\n")
    return outs,errs,last,last_cols,enabled,cursor

