        if mgmt[0] in ("-h","--help"):
            sys.stdout.write(f"The Logfile Navigator\nUsage: {prog} [OPTIONS] [SUBCOMMAND]\n\nOptions:\n  -h,--help                   Print this help message and exit\n  -d FILE                     Write debug messages to the given file.\n  -D                          Enable debugging of notcurses\n  -I TEXT:DIR ...             include paths\n  -q{{0}},-v{{2}}                 Control the verbosity\n  -V,--version                Display program version information and exit\n  -m                          Switch to the management CLI mode.\n\nSubcommands:\n  apps                        manage lnav apps\n  config                      perform operations on the lnav configuration\n  format                      perform operations on log file formats\n  piper                       perform operations on piper storage\n  regex101                    create and edit log message regular expressions using regex101.com\n  crash                       manage crash logs\n\nVersion: lnav 0.14.0-8ad2d43\n")
            sys.exit(0)
        if "-V" in mgmt or "--version" in mgmt:
            sys.stdout.write(VERSION+"\n")
            sys.exit(0)
        # parse global -d, -I before subcmd
        idx=0
        while idx < len(mgmt):
            if mgmt[idx]=="-d":
                if idx+1>=len(mgmt):
                    sys.stderr.write("  error: invalid command-line arguments\n reason: -d: 1 required FILE missing\n")
                    sys.exit(114)
                try:
                    open(mgmt[idx+1],'a').close()
                except:
                    pass
                idx+=2
            elif mgmt[idx]=="-I":
                idx+=2
            elif mgmt[idx] in ("-h","--help"):
                break
            elif mgmt[idx].startswith("-"):
                if mgmt[idx] not in ("-D","-q","-v"):
                    sys.stderr.write(f"  error: invalid command-line arguments\n reason: The following argument was not expected: {mgmt[idx]}\n")
                    sys.exit(109)
                idx+=1
            else:
                break
