            else:
                return not any(pp.lower() in b.lower() for pp in out_pats)
        for ii,e in enumerate(filtered):
            if ii < cursor: continue
            body=e.get('log_body','')
            if not passes_raw(body): continue
            sys.stdout.write(e.get('raw','')+"\n")

