def parse_time(s):
    if s=="":
        return datetime.datetime.min.replace(tzinfo=timezone.utc)
    if re.fullmatch(r"\d+",s.strip()):
        raise ValueError(f"  error: invalid 'since' time \u201c{s}\u201d\n reason: Number given without a time unit\n")
