    filtered.extend(filter_time(shell_stdin,since_dt,until_dt))

    if ooo and not filtered and not ordered_cmds:
        fp,c,mt=ooo[0]
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)
