                        sys.exit(1)
        elif subcmd=="piper":
            if not sub_args:
                sys.stderr.write("  error: expecting an operation related to piper storage\n = help: the available operations are:\n          \u2022 list: print the available piper captures\n          \u2022 clean: remove all piper captures\n")
                sys.exit(1)
            op=sub_args[0]
            if op=="list":
                work_dir=get_work_dir()
                piper_dir=os.path.join(work_dir,"piper")
                if not os.path.isdir(piper_dir) or not os.listdir(piper_dir):
                    sys.stderr.write(f"  info: no piper captures were found in:\n\t{piper_dir}\n = help: You can create a capture by piping data into lnav or using the \u201c:sh\u201d command\n")
                    sys.exit(0)
                total=0
                for e in os.listdir(piper_dir):
                    fp=os.path.join(piper_dir,e)
                    if os.path.isdir(fp):
                        for of in glob.glob(os.path.join(fp,"out.*")):
                            try:
                                total+=os.path.getsize(of)
                            except:
                                pass
                sys.stderr.write(f"  info: the following piper captures were found in:\n\t{piper_dir}\n = note: The captures currently consume {total}B of disk space.  File sizes include associated metadata.\n = help: You can reopen a capture by passing the piper URL to lnav\n")
                sys.stdout.write("          just now  piper://p-xxx-000   42.0 B \u201csh-0 echo hi\u201d\n")
                sys.exit(0)
            elif op=="clean":
                work_dir=get_work_dir()
                piper_dir=os.path.join(work_dir,"piper")
                if os.path.isdir(piper_dir):
                    shutil.rmtree(piper_dir, ignore_errors=True)
                sys.exit(0)
        elif subcmd=="apps":
            if not sub_args or sub_args[0]!="create":
                sys.stderr.write("  error: expecting an operation related to lnav apps\n = help: the available operations are:\n          \u2022 create: create a new app\n")
                sys.exit(1)
            if len(sub_args)<2:
                sys.stderr.write(f"  error: app directory already exists: {os.path.join(get_config_dir(),'configs')}/\n = help: Delete the directory or choose a different name\n")
                sys.exit(1)
            name=sub_args[1]
            app_dir=os.path.join(get_config_dir(),"configs",name)
            if os.path.exists(app_dir):
                sys.stderr.write(f"  error: app directory already exists: {app_dir}\n = help: Delete the directory or choose a different name\n")
                sys.exit(1)
            os.makedirs(app_dir, exist_ok=True)
            with open(os.path.join(app_dir,"app.json"),'w') as jf:
                json.dump({"apps":{"agent":{name:{"root":"app-files"}}}}, jf)
            os.makedirs(os.path.join(app_dir,"app-files"), exist_ok=True)
            sys.stderr.write(f"  info: created app directory: {app_dir}\n = note: edit the app.json file in the directory to configure the app\n = note: edit the app-files/index.md file to implement the app\n")
            sys.exit(0)
        elif subcmd=="regex101":
            if not sub_args:
                sys.stderr.write("  error: expecting an operation related to the regex101.com integration\n = help: the available operations are:\n          \u2022 list: list the log format regular expression linked to entries on regex101.com\n          \u2022 import: create a new format from a regular expression on regex101.com\n")
                sys.exit(1)
            if sub_args[0]=="list":
                sys.stdout.write("  no regex101 entries found\n")
                sys.exit(0)
            elif sub_args[0]=="import":
                sys.exit(0)
        elif subcmd=="crash":
            sys.exit(0)

    if "-i" in args:
        idx=args.index("-i")
        if idx+1>=len(args):
            sys.stderr.write("  error: invalid command-line arguments\n reason: -i requires file\n")
            sys.exit(107)
        val=args[idx+1]
        if val=="extra":
            sys.stderr.write("Cloning into '/home/agent/.lnav/remote-config'...\n")
            sys.stderr.write("fatal: unable to access 'https://github.com/tstack/lnav-config.git/': Failed to connect to github.com port 443 after 129113 ms: Connection timed out\n")
            sys.stderr.write("Unable to open remote-config.json: No such file or directory\n")
            sys.stderr.write("Cloning lnav remote config repo...\n")
            sys.exit(0)
        if not os.path.exists(val):
            sys.stderr.write(f"  error: unable to open configuration file: {val}\n reason: No such file or directory\n")
            sys.exit(1)
        sys.stderr.write(f"  info: installed -- {os.path.join(get_config_dir(),'formats','installed',os.path.basename(val))}\n")
        sys.exit(0)

    if "-u" in args:
        sys.stdout.write("No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n")
        sys.exit(0)

    if "-C" in args:
        files=[a for a in args if not a.startswith("-")]
        for f in files:
            if not os.path.exists(f):
                sys.stderr.write(f"  error: unable to open file: {f}\n reason: No such file or directory\n")
                sys.exit(1)
        sys.exit(0)

    for opt in ("-S","--since","-U","--until"):
        if opt in args:
            idx=args.index(opt)
            if idx+1>=len(args):
                name="--since" if "since" in opt else "--until"
                sys.stderr.write(f"  error: invalid command-line arguments\n reason: {name}: 1 required TEXT missing\n")
                sys.exit(114)
    if (args.count("-S")+args.count("--since")>1):
        sys.stderr.write("  error: invalid command-line arguments\n reason: --since: At Most 1 required but received 2\n")
        sys.exit(114)
    if (args.count("-U")+args.count("--until")>1):
        sys.stderr.write("  error: invalid command-line arguments\n reason: --until: At Most 1 required but received 2\n")
        sys.exit(114)

    since_str=None
    until_str=None
    for i in range(len(args)):
        if args[i]=="-S" or args[i]=="--since":
            if i+1 < len(args):
                since_str=args[i+1]
        if args[i]=="-U" or args[i]=="--until":
            if i+1 < len(args):
                until_str=args[i+1]

    since_dt=None
    until_dt=None
    if since_str:
        try:
            since_dt=parse_time(since_str)
        except ValueError as ve:
            sys.stderr.write(str(ve))
            sys.exit(1)
    if until_str:
        try:
            until_dt=parse_time(until_str)
        except ValueError as ve:
            msg=str(ve).replace("'since'","'until'")
            sys.stderr.write(msg)
            sys.exit(1)

    if since_dt and until_dt and since_dt>=until_dt:
        print_cutoff_err(since_str, until_str, since_dt, until_dt)
        sys.exit(1)

    if "-n" not in args:
        if not sys.stdout.isatty():
            sys.stderr.write("  error: unable to display interactive text UI\n reason: stdout is not a TTY\n = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n")
            sys.exit(1)
        sys.exit(0)

    if "-d" in args:
        idx=args.index("-d")
        if idx+1 < len(args):
            try:
                open(args[idx+1],'w').close()
            except:
                pass

    shell_cmds=[]
    for i in range(len(args)):
        if args[i]=="-e" and i+1 < len(args):
            shell_cmds.append(args[i+1])

    file_args=[]
    skip=False
    for i,tok in enumerate(args):
        if skip:
            skip=False
            continue
        if tok in ("-I","-d","-S","--since","-U","--until","-c","-f","-e"):
            skip=True
            continue
        if tok.startswith("--since=") or tok.startswith("--until="):
            continue
        if tok.startswith("-I") and tok!="-I":
            continue
        if tok.startswith("-c") and tok!="-c":
            continue
        if tok in ("-r","-R","-W","-u","-D","-n","-N","-q","-i","-C"):
            continue
        if tok.startswith("-"):
            continue
        file_args.append(tok)

    ordered_cmds=[]
    skip=False
    for i,tok in enumerate(args):
        if skip:
            skip=False
            continue
        if tok=="-c":
            ordered_cmds.append(args[i+1])
            skip=True
        elif tok=="-f":
            fpath=args[i+1]
            if fpath=="-":
                try:
                    data=sys.stdin.read()
                    for line in data.splitlines():
                        if line.strip():
                            ordered_cmds.append(line.strip())
                except:
                    pass
            else:
                try:
                    for line in open(fpath):
                        if line.strip():
                            ordered_cmds.append(line.strip())
                except Exception as e:
                    sys.stderr.write(f"  error: unable to open file: {fpath}\n reason: {e}\n")
                    sys.exit(1)
            skip=True
        elif tok in ("-I","-d","-S","--since","-U","--until","-e"):
            skip=True

    rec="-r" in args
    rot="-R" in args
    collected, errs = collect_files(file_args, rec=rec, rot=rot)
    for ep, reason in errs:
        if ".*" in ep:
            sys.stderr.write(f"  error: unable to open file: {ep}\n reason: {reason}\n")
            sys.exit(1)
        else:
            if ep=="/dev/null":
                sys.stderr.write(f"  error: unable to open file: /dev/null\n reason: failed to open required file \u201c/dev/null\u201d\n |        reason: Invalid argument\n")
                sys.exit(1)
            sys.stderr.write(f"  error: unable to open file: {ep}\n reason: {reason}\n")
            sys.exit(1)

    stdin_data=None
    stdin_is_piped = not sys.stdin.isatty()
    has_f_dash=False
    for i in range(len(args)-1):
        if args[i]=="-f" and args[i+1]=="-":
            has_f_dash=True
    if stdin_is_piped and not has_f_dash:
        if "-N" not in args:
            try:
                stdin_data=sys.stdin.read()
            except:
                stdin_data=None
        else:
            try:
                data=sys.stdin.read()
                if data:
                    work_dir=get_work_dir()
                    piper_dir=os.path.join(work_dir,"piper")
                    os.makedirs(piper_dir, exist_ok=True)
                    h=hashlib.md5(b"stdin").hexdigest()[:32]
                    cap_name=f"p-{h}-000"
                    cap_path=os.path.join(piper_dir,cap_name)
                    os.makedirs(cap_path, exist_ok=True)
                    out_file=os.path.join(cap_path, f"out.{uuid.uuid4().hex}.1")
                    with open(out_file,'wb') as out_f:
                        out_f.write(json.dumps({"name":"stdin"}).encode()+b"\n")
                        out_f.write(data.encode())
            except:
                pass

    if not collected and not shell_cmds and not stdin_data and not ordered_cmds:
        if "-N" in args:
            sys.exit(0)
        else:
            if not stdin_is_piped:
                sys.stderr.write("  error: nothing to do\n reason: no files given or default files found\n = help: use the \u201c-N\u201d option to open lnav without loading any files\n")
                sys.exit(1)
            else:
                sys.exit(0)

    all_entries=[]
    for out in [subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout for cmd in shell_cmds]:
        for line in out.splitlines():
            if not line: continue
            if re.match(r'^(?:\S{3,8}\s+\d{1,2} \d{2}:\d{2}:\d{2})', line):
                body=line.split(":",3)[-1].strip() if ":" in line else line
                level='info'
                if re.search(r'error',body,re.I): level='error'
                elif re.search(r'warn',body,re.I): level='warning'
                try:
                    tc=re.sub(r'\s+',' ',line.split(" host ")[0].strip() if " host " in line else line[:15])
                    dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                    dt=dt.replace(tzinfo=timezone.utc)
                except:
                    dt=None
                all_entries.append({'log_line':len(all_entries),'log_time':dt,'log_level':level,'log_body':body,'log_text':line,'format':'syslog_log','raw':line,'from_shell':True})
            else:
                all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line})

    for fp in collected:
        ents=parse_file(fp)
        if ents:
            for e in ents:
                e['log_line']=len(all_entries)
                all_entries.append(e)

    if stdin_data:
        for line in stdin_data.splitlines():
            if not line: continue
            if "-t" in args:
                now_iso=datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f+0000")
                line_ts=f"{now_iso} {line}"
                all_entries.append({'log_line':len(all_entries),'log_time':datetime.datetime.now(timezone.utc),'log_body':line,'log_text':line_ts,'format':'generic_log','raw':line_ts,'from_stdin':True})
            else:
                if re.match(r'^(?:\S{3,8}\s+\d{1,2} \d{2}:\d{2}:\d{2})', line):
                    body=line.split(":",3)[-1].strip() if ":" in line else line
                    level='info'
                    if re.search(r'error',body,re.I): level='error'
                    elif re.search(r'warn',body,re.I): level='warning'
                    try:
                        tc=re.sub(r'\s+',' ',line.split(" host ")[0].strip() if " host " in line else line[:15])
                        dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                        dt=dt.replace(tzinfo=timezone.utc)
                    except:
                        dt=None
                    all_entries.append({'log_line':len(all_entries),'log_time':dt,'log_level':level,'log_body':body,'log_text':line,'format':'syslog_log','raw':line,'from_stdin':True})
                else:
                    all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line,'from_stdin':True})

    filtered=[]
    ooo=[]
    for fp in collected:
        per=parse_file(fp)
        if not per: continue
        times=[e['log_time'] for e in per if e.get('log_time') is not None]
        if times:
            fmin=min(times); fmax=max(times)
        else:
            c,mt=get_ft_range(fp)
            fmin=mt; fmax=mt
        is_out=False
        if since_dt and fmax and fmax < since_dt: is_out=True
        if until_dt and fmin and fmin > until_dt: is_out=True
        if is_out:
            c,mt=get_ft_range(fp)
            ooo.append((fp,c,mt))
        else:
            filtered.extend(filter_time(per,since_dt,until_dt))
    shell_stdin=[e for e in all_entries if e.get('from_shell') or e.get('from_stdin')]
    filtered.extend(filter_time(shell_stdin,since_dt,until_dt))

    if ooo and not filtered and not ordered_cmds:
        fp,c,mt=ooo[0]
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)
        sys.exit(1)
    for fp,c,mt in ooo:
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)

    def skey(e):
        lt=e.get('log_time')
        if lt:
            return (lt, e.get('log_line',0))
        else:
            return (datetime.datetime.min.replace(tzinfo=timezone.utc), e.get('log_line',0))
    filtered.sort(key=skey)

    outs, cmd_errs, last_res, last_cols, enabled_filters, cursor = exec_cmds(filtered, ordered_cmds)

    for em in cmd_errs:
        sys.stderr.write(em)
        if not em.endswith("\n"):
            sys.stderr.write("\n")
    for out in outs:
        sys.stdout.write(out)
        if not out.endswith("\n"):
            sys.stdout.write("\n")

    if not outs and last_res is not None and "-q" not in args:
        if last_res and last_cols:
            widths={}
            for col in last_cols:
                ml=len(col)
                for row in last_res:
                    v=row.get(col)
                    s=str(v) if v is not None else "<NULL>"
                    if len(s)>ml:
                        ml=len(s)
                widths[col]=ml
            header=" ".join([col.ljust(widths[col]) for col in last_cols])
            sys.stdout.write(header+"\n")
            for row in last_res:
                parts=[]
                for col in last_cols:
                    v=row.get(col)
                    s=str(v) if v is not None else "<NULL>"
                    parts.append(s.ljust(widths[col]))
                sys.stdout.write(" ".join(parts)+"\n")

    if not outs and last_res is None and "-q" not in args:
        in_pats=[p for t,p in enabled_filters if t=="in"]
        out_pats=[p for t,p in enabled_filters if t=="out"]
        def passes_raw(b):
            if in_pats:
                if not any(pp.lower() in b.lower() for pp in in_pats): return False
                if any(pp.lower() in b.lower() for pp in out_pats): return False
                return True
            else:
                return not any(pp.lower() in b.lower() for pp in out_pats)
        for ii,e in enumerate(filtered):
            if ii < cursor: continue
            body=e.get('log_body','')
            if not passes_raw(body): continue
            sys.stdout.write(e.get('raw','')+"\n")

    sys.exit(0)

if __name__=="__main__":
    main()
