    res=[]
    for e in ents:
        lt=e.get('log_time')
        if lt is None:
            res.append(e)
            continue
        if since_dt and lt < since_dt: continue
        if until_dt and lt > until_dt: continue
        res.append(e)
    return res
def collect_files(paths,rec=False,rot=False):
    res=[]; errs=[]
    for p in paths:
        if os.path.isdir(p):
            if rec:
                for root,dirs,files in os.walk(p):
                    for f in files:
                        fp=os.path.join(root,f)
                        if os.path.isfile(fp):
                            res.append(fp)
            else:
                try:
                    for f in os.listdir(p):
                        fp=os.path.join(p,f)
                        if os.path.isfile(fp):
                            res.append(fp)
                except Exception as e:
                    errs.append((p,str(e)))
        else:
            if rot:
                pat=p+".*"
                matched=glob.glob(pat)
                if not matched:
                    errs.append((pat,f"failed to find path of \u201c{pat}\u201d\n |        reason: No such file or directory"))
                    continue
                if os.path.isfile(p):
                    res.append(p)
                for mm in matched:
                    if os.path.isfile(mm):
                        res.append(mm)
            else:
                if os.path.isfile(p):
                    res.append(p)
                else:
                    mm=glob.glob(p)
                    if mm:
                        for mm2 in mm:
                            if os.path.isfile(mm2):
                                res.append(mm2)
                    else:
                        errs.append((p,"No such file or directory"))
    return res,errs
