                    all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line,'from_stdin':True})

    filtered=[]
    ooo=[]
    for fp in collected:
        per=parse_file(fp)
        if not per: continue
        times=[e['log_time'] for e in per if e.get('log_time') is not None]
        if times:
            fmin=min(times); fmax=max(times)
        else:
            c,mt=get_ft_range(fp)
            fmin=mt; fmax=mt
