            sys.exit(107)
        val=args[idx+1]
        if val=="extra":
            sys.stderr.write("Cloning into '/home/agent/.lnav/remote-config'...\n")
            sys.stderr.write("fatal: unable to access 'https://github.com/tstack/lnav-config.git/': Failed to connect to github.com port 443 after 129113 ms: Connection timed out\n")
            sys.stderr.write("Unable to open remote-config.json: No such file or directory\n")
            sys.stderr.write("Cloning lnav remote config repo...\n")
            sys.exit(0)
        if not os.path.exists(val):
            sys.stderr.write(f"  error: unable to open configuration file: {val}\n reason: No such file or directory\n")
            sys.exit(1)
        sys.stderr.write(f"  info: installed -- {os.path.join(get_config_dir(),'formats','installed',os.path.basename(val))}\n")
        sys.exit(0)

    if "-u" in args:
        sys.stdout.write("No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n")
        sys.exit(0)

    if "-C" in args:
        files=[a for a in args if not a.startswith("-")]
        for f in files:
            if not os.path.exists(f):
                sys.stderr.write(f"  error: unable to open file: {f}\n reason: No such file or directory\n")
                sys.exit(1)
        sys.exit(0)

    for opt in ("-S","--since","-U","--until"):
        if opt in args:
            idx=args.index(opt)
            if idx+1>=len(args):
                name="--since" if "since" in opt else "--until"
                sys.stderr.write(f"  error: invalid command-line arguments\n reason: {name}: 1 required TEXT missing\n")
                sys.exit(114)
    if (args.count("-S")+args.count("--since")+sum(1 for a in args if a.startswith("--since="))>1):
        sys.stderr.write("  error: invalid command-line arguments\n reason: --since: At Most 1 required but received 2\n")
        sys.exit(114)
    if (args.count("-U")+args.count("--until")+sum(1 for a in args if a.startswith("--until="))>1):
        sys.stderr.write("  error: invalid command-line arguments\n reason: --until: At Most 1 required but received 2\n")
        sys.exit(114)

    known_opts=["-h","--help","-H","-I","-W","-u","-d","-V","--version","-S","--since","-U","--until","-r","-R","-c","-f","-e","-t","-n","-N","-q","-i","-C","-D"]
    for tok in args:
        if tok.startswith("-"):
            if tok.startswith("--since=") or tok.startswith("--until="):
                continue
            if tok.startswith("-I") and tok!="-I":
                continue
            if tok.startswith("-c") and tok!="-c":
                continue
            if tok in known_opts:
                continue
            sys.stderr.write(f"  error: invalid command-line arguments\n reason: The following argument was not expected: {tok}\n")
            sys.exit(109)

    since_str=None
    until_str=None
    for i in range(len(args)):
        if args[i]=="-S" or args[i]=="--since":
            if i+1 < len(args):
                since_str=args[i+1]
        if args[i]=="-U" or args[i]=="--until":
            if i+1 < len(args):
                until_str=args[i+1]
        if args[i].startswith("--since="):
            since_str=args[i].split("=",1)[1]
        if args[i].startswith("--until="):
            until_str=args[i].split("=",1)[1]

    since_dt=None
    until_dt=None
    if since_str:
        try:
            since_dt=parse_time(since_str)
        except ValueError as ve:
            sys.stderr.write(str(ve))
            sys.exit(1)
    if until_str:
        try:
            until_dt=parse_time(until_str)
        except ValueError as ve:
            msg=str(ve).replace("'since'","'until'")
            sys.stderr.write(msg)
