                pass

    shell_cmds=[]
    for i in range(len(args)):
        if args[i]=="-e" and i+1 < len(args):
            shell_cmds.append(args[i+1])

    file_args=[]
    skip=False
    for i,tok in enumerate(args):
        if skip:
            skip=False
            continue
        if tok in ("-I","-d","-S","--since","-U","--until","-c","-f","-e"):
            skip=True
            continue
        if tok.startswith("--since=") or tok.startswith("--until="):
            continue
        if tok.startswith("-I") and tok!="-I":
            continue
        if tok.startswith("-c") and tok!="-c":
            continue
        if tok in ("-r","-R","-W","-u","-D","-n","-N","-q","-i","-C"):
            continue
        if tok.startswith("-"):
            continue
        file_args.append(tok)

    ordered_cmds=[]
    skip=False
    for i,tok in enumerate(args):
        if skip:
            skip=False
            continue
        if tok=="-c":
            ordered_cmds.append(args[i+1])
