        elif tok=="-f":
            fpath=args[i+1]
            if fpath=="-":
                try:
                    data=sys.stdin.read()
                    for line in data.splitlines():
                        if line.strip():
                            ordered_cmds.append(line.strip())
                except:
                    pass
            else:
                try:
                    for line in open(fpath):
                        if line.strip():
                            ordered_cmds.append(line.strip())
                except Exception as e:
                    sys.stderr.write(f"  error: unable to open file: {fpath}\n reason: {e}\n")
                    sys.exit(1)
            skip=True
        elif tok in ("-I","-d","-S","--since","-U","--until","-e"):
            skip=True

    rec="-r" in args
    rot="-R" in args
    collected, errs = collect_files(file_args, rec=rec, rot=rot)
    for ep, reason in errs:
        if ".*" in ep:
            sys.stderr.write(f"  error: unable to open file: {ep}\n reason: {reason}\n")
