                else:
                    all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line,'from_stdin':True})

    filtered=[]
    ooo=[]
    for fp in collected:
        per=parse_file(fp)
