def fmt_err(dt):
    return dt.strftime("%Y-%m-%d %H:%M:%S.%f")
def get_ft_range(p):
    try:
        st=os.stat(p)
        c=datetime.datetime.fromtimestamp(st.st_ctime,tz=timezone.utc)
        mt=datetime.datetime.fromtimestamp(st.st_mtime,tz=timezone.utc)
        return c,mt
    except:
        return None,None
