        else:
            try:
                data=sys.stdin.read()
                if data:
                    work_dir=get_work_dir()
                    piper_dir=os.path.join(work_dir,"piper")
                    os.makedirs(piper_dir, exist_ok=True)
                    h=hashlib.md5(b"stdin").hexdigest()[:32]
                    cap_name=f"p-{h}-000"
                    cap_path=os.path.join(piper_dir,cap_name)
                    os.makedirs(cap_path, exist_ok=True)
                    out_file=os.path.join(cap_path, f"out.{uuid.uuid4().hex}.1")
                    with open(out_file,'wb') as out_f:
                        out_f.write(json.dumps({"name":"stdin"}).encode()+b"\n")
                        out_f.write(data.encode())
            except:
                pass

    if not collected and not shell_cmds and not stdin_data and not ordered_cmds:
        if "-N" in args:
            sys.exit(0)
        else:
            if not stdin_is_piped:
                sys.stderr.write("  error: nothing to do\n reason: no files given or default files found\n = help: use the \u201c-N\u201d option to open lnav without loading any files\n")
                sys.exit(1)
            else:
                sys.exit(0)

    all_entries=[]
    for out in [subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout for cmd in shell_cmds]:
        for line in out.splitlines():
            if not line: continue
            if re.match(r'^(?:\S{3,8}\s+\d{1,2} \d{2}:\d{2}:\d{2})', line):
                body=line.split(":",3)[-1].strip() if ":" in line else line
                level='info'
                if re.search(r'error',body,re.I): level='error'
                elif re.search(r'warn',body,re.I): level='warning'
                try:
                    tc=re.sub(r'\s+',' ',line.split(" host ")[0].strip() if " host " in line else line[:15])
                    dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                    dt=dt.replace(tzinfo=timezone.utc)
                except:
                    dt=None
                all_entries.append({'log_line':len(all_entries),'log_time':dt,'log_level':level,'log_body':body,'log_text':line,'format':'syslog_log','raw':line,'from_shell':True})
            else:
                all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line})

