            except:
                dt=None
            ents.append({'log_line':idx,'log_time':dt,'log_level':'unknown','log_body':body,'log_text':orig,'format':'generic_log','raw':orig})
            continue
        m=syslog_std.match(orig)
        if m:
            ts=m.group('timestamp')
            hostname=m.group('hostname') or 'host'
            tag=m.group('tag') or ''
            body=m.group('body') or ''
            level='info'
            if re.search(r'error',body,re.I): level='error'
            elif re.search(r'warn',body,re.I): level='warning'
            try:
                tc=re.sub(r'\s+',' ',ts.strip())
                dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                dt=dt.replace(tzinfo=timezone.utc)
            except:
                dt=None
            proc=tag.split('[')[0] if '[' in tag else tag
            ents.append({'log_line':idx,'log_time':dt,'log_level':level,'log_hostname':hostname,'log_procname':proc,'log_syslog_tag':tag,'log_body':body,'log_text':orig,'format':'syslog_log','raw':orig})
            continue
        m=access_std.match(orig)
        if m:
            ts=m.group('timestamp')
            try:
                dt=datetime.datetime.strptime(ts,"%d/%b/%Y:%H:%M:%S %z")
                dt=dt.astimezone(timezone.utc)
            except:
                dt=None
            ents.append({'log_line':idx,'log_time':dt,'log_level':'info','log_body':orig,'log_text':orig,'format':'access_log','raw':orig,'c_ip':m.group('ip'),'cs_username':m.group('user'),'cs_method':m.group('method'),'cs_uri_stem':m.group('uri'),'sc_status':m.group('status'),'sc_bytes':m.group('bytes')})
            continue
        ents.append({'log_line':idx,'log_time':None,'log_level':'unknown','log_body':orig,'log_text':orig,'format':'text','raw':orig})
    return ents

def filter_time(ents,since_dt,until_dt):
    res=[]
    for e in ents:
        lt=e.get('log_time')
        if lt is None:
            res.append(e)
            continue
        if since_dt and lt < since_dt: continue
        if until_dt and lt > until_dt: continue
        res.append(e)
    return res

def collect_files(paths,rec=False,rot=False):
    res=[]; errs=[]
    for p in paths:
        if os.path.isdir(p):
            if rec:
                for root,dirs,files in os.walk(p):
                    for f in files:
                        fp=os.path.join(root,f)
                        if os.path.isfile(fp):
                            res.append(fp)
            else:
                try:
                    for f in os.listdir(p):
                        fp=os.path.join(p,f)
                        if os.path.isfile(fp):
                            res.append(fp)
                except Exception as e:
                    errs.append((p,str(e)))
        else:
            if rot:
                pat=p+".*"
                matched=glob.glob(pat)
                if not matched:
                    errs.append((pat,f"failed to find path of \u201c{pat}\u201d\n |        reason: No such file or directory"))
                    continue
                if os.path.isfile(p):
                    res.append(p)
                for mm in matched:
                    if os.path.isfile(mm):
                        res.append(mm)
            else:
                if os.path.isfile(p):
                    res.append(p)
                else:
                    mm=glob.glob(p)
                    if mm:
                        for mm2 in mm:
                            if os.path.isfile(mm2):
                                res.append(mm2)
                    else:
                        errs.append((p,"No such file or directory"))
    return res,errs

def exec_cmds(ents,cmds):
    outs=[]; errs=[]; last=None; last_cols=None; seen=set(); enabled=[]; cursor=0
    def skey(e):
        lt=e.get('log_time')
        if lt:
            return (lt, e.get('log_line',0))
        else:
            return (datetime.datetime.min.replace(tzinfo=timezone.utc), e.get('log_line',0))
    esorted=sorted(ents,key=skey)
    bodies=[e.get('log_body','') for e in esorted]
    view="log"
    for idx_cmd,cmd in enumerate(cmds):
        cs=cmd.strip()
        if not cs: continue
        fc=cs[0]
        if fc==":":
            inner=cs[1:].strip()
            if not inner:
