                            if any(pp.lower() in b.lower() for pp in out_pats): return False
                            return True
                        else:
                            return not any(pp.lower() in b.lower() for pp in out_pats)
                    first=None
                    for ii,bb in enumerate(bodies):
                        if passes(bb):
                            first=ii
                            break
                    if first is not None and first>cursor:
