                    continue
                parts=carg.split()
                if parts and parts[0]=="--anonymize":
                    parts=parts[1:]
                if not parts:
                    errs.append(f"  error: expecting file name or '-' to write to the terminal\n --> command-option:{idx_cmd+1}\n | :{cname}                           \n = help: :{cname} [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Write SQL results to the given file in {'CSV' if 'csv' in cname else 'JSON'} format\n")
                    continue
                path_arg=parts[0]
                if last is None:
                    errs.append(f"  error: no query result to write, use ';' to execute a query\n --> command-option:{idx_cmd+1}\n | :{cname} {carg}                         \n = help: :{cname} [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Write SQL results to the given file in {'CSV' if 'csv' in cname else 'JSON'} format\n")
                    continue
                if path_arg=="-":
                    if "csv" in cname:
                        if last_cols:
                            lines=[",".join(last_cols)]
                            for row in last:
                                vals=[]
                                for col in last_cols:
                                    v=row.get(col)
                                    if v is None:
                                        vals.append("<NULL>")
                                    else:
                                        s=str(v)
                                        if "," in s or '"' in s:
                                            s='"'+s.replace('"','""')+'"'
                                        vals.append(s)
                                lines.append(",".join(vals))
                            outs.append("\n".join(lines)+"\n")
                    else:
                        outs.append(json.dumps(last,indent=4)+"\n")
                else:
                    try:
                        with open(path_arg,'w') as out_f:
                            if "csv" in cname:
                                if last_cols:
                                    out_f.write(",".join(last_cols)+"\n")
                                    for row in last:
                                        vals=[]
                                        for col in last_cols:
                                            v=row.get(col)
                                            if v is None:
                                                vals.append("<NULL>")
                                            else:
                                                s=str(v)
                                                if "," in s or '"' in s:
                                                    s='"'+s.replace('"','""')+'"'
                                                vals.append(s)
                                        out_f.write(",".join(vals)+"\n")
                            else:
                                json.dump(last,out_f,indent=4)
                                out_f.write("\n")
                    except Exception as e:
                        errs.append(f"  error: unable to write file: {path_arg}\n reason: {e}\n")
            elif cname=="help":
                pass
            elif cname=="goto":
                try:
                    if carg.isdigit():
                        n=int(carg)
                        if 0 <= n-1 < len(esorted):
                            cursor=max(cursor,n-1)
                except:
                    pass
            elif cname=="open":
                if not carg:
                    errs.append(f"  error: expecting a file name to open\n")
                else:
                    if not os.path.exists(carg):
                        errs.append(f"  error: cannot open file: {carg}\n reason: No such file or directory\n --> command-option:{idx_cmd+1}\n | :open {carg}                      \n = help: make sure the file exists and is accessible\n")
            elif cname=="write-to":
                errs.append(f"  error: no lines marked to write, use 'm' to mark lines\n --> command-option:{idx_cmd+1}\n | :write-to {carg}             \n = help: :write-to [--anonymize] path\n         \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n           Overwrite the given file with any marked lines in the current view\n")
            else:
                errs.append(f"  error: unknown command: \u201c{cname}\u201d\n")
        elif fc==";":
            sql=cs[1:].strip()
            if not sql:
                last=[]; last_cols=[]; view="db"; continue
            m_from=re.search(r"FROM\s+(\w+)",sql,re.IGNORECASE)
            if not m_from:
                if re.match(r"^\s*SELECT\s+\d+\s*$",sql,re.IGNORECASE):
                    num=re.search(r"\d+",sql).group(0)
                    last=[{num:int(num)}]; last_cols=[num]; view="db"; continue
                else:
                    errs.append(f"  error: failed to compile SQL statement\n reason: near \".\": syntax error\n --> command-option:{idx_cmd+1}\n | {sql}                                 \n")
                    last=None; last_cols=None; view="db"; continue
            table=m_from.group(1)
            if table=="lnav_view":
                errs.append(f"  error: failed to compile SQL statement\n reason: no such table: {table}\n --> command-option:{idx_cmd+1}\n | {sql}                \n")
                last=None; last_cols=None; view="db"; continue
            if table not in ("syslog_log","generic_log","access_log","logline","lnav_view_filters","sqlite_master"):
                errs.append(f"  error: failed to compile SQL statement\n reason: no such table: {table}\n --> command-option:{idx_cmd+1}\n | {cs}                      \n")
                last=None; last_cols=None; view="db"; continue
            m_sel=re.search(r"SELECT\s+(.*?)\s+FROM",sql,re.IGNORECASE|re.DOTALL)
            if m_sel:
                cols_str=m_sel.group(1).strip()
                cols_str=re.sub(r"(?i)DISTINCT","",cols_str).strip()
                if re.match(r"COUNT\s*\(\s*\*\s*\)",cols_str,re.IGNORECASE):
                    in_pats=[p for t,p in enabled if t=="in"]; out_pats=[p for t,p in enabled if t=="out"]
                    def passes(b):
                        if in_pats:
                            if not any(pp.lower() in b.lower() for pp in in_pats): return False
                            if any(pp.lower() in b.lower() for pp in out_pats): return False
