    for out in [subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout for cmd in shell_cmds]:
        for line in out.splitlines():
            if not line: continue
            if re.match(r'^(?:\S{3,8}\s+\d{1,2} \d{2}:\d{2}:\d{2})', line):
                body=line.split(":",3)[-1].strip() if ":" in line else line
                level='info'
                if re.search(r'error',body,re.I): level='error'
                elif re.search(r'warn',body,re.I): level='warning'
                try:
                    tc=re.sub(r'\s+',' ',line.split(" host ")[0].strip() if " host " in line else line[:15])
                    dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                    dt=dt.replace(tzinfo=timezone.utc)
                except:
                    dt=None
                all_entries.append({'log_line':len(all_entries),'log_time':dt,'log_level':level,'log_body':body,'log_text':line,'format':'syslog_log','raw':line,'from_shell':True})
            else:
                all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line})

    for fp in collected:
        ents=parse_file(fp)
        if ents:
            for e in ents:
                e['log_line']=len(all_entries)
                all_entries.append(e)

    if stdin_data:
        for line in stdin_data.splitlines():
            if not line: continue
            if "-t" in args:
                now_iso=datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f+0000")
                line_ts=f"{now_iso} {line}"
                all_entries.append({'log_line':len(all_entries),'log_time':datetime.datetime.now(timezone.utc),'log_body':line,'log_text':line_ts,'format':'generic_log','raw':line_ts,'from_stdin':True})
            else:
                if re.match(r'^(?:\S{3,8}\s+\d{1,2} \d{2}:\d{2}:\d{2})', line):
                    body=line.split(":",3)[-1].strip() if ":" in line else line
                    level='info'
                    if re.search(r'error',body,re.I): level='error'
                    elif re.search(r'warn',body,re.I): level='warning'
                    try:
                        tc=re.sub(r'\s+',' ',line.split(" host ")[0].strip() if " host " in line else line[:15])
                        dt=datetime.datetime.strptime(f"{tc} 2026","%b %d %H:%M:%S %Y")
                        dt=dt.replace(tzinfo=timezone.utc)
                    except:
                        dt=None
                    all_entries.append({'log_line':len(all_entries),'log_time':dt,'log_level':level,'log_body':body,'log_text':line,'format':'syslog_log','raw':line,'from_stdin':True})
                else:
                    all_entries.append({'log_line':len(all_entries),'log_time':None,'log_body':line,'log_text':line,'format':'text','raw':line,'from_stdin':True})

    filtered=[]
    ooo=[]
    for fp in collected:
        per=parse_file(fp)
        if not per: continue
        times=[e['log_time'] for e in per if e.get('log_time') is not None]
        if times:
            fmin=min(times); fmax=max(times)
        else:
            c,mt=get_ft_range(fp)
            fmin=mt; fmax=mt
        is_out=False
        if since_dt and fmax and fmax < since_dt: is_out=True
        if until_dt and fmin and fmin > until_dt: is_out=True
        if is_out:
            c,mt=get_ft_range(fp)
            ooo.append((fp,c,mt))
        else:
            filtered.extend(filter_time(per,since_dt,until_dt))
    shell_stdin=[e for e in all_entries if e.get('from_shell') or e.get('from_stdin')]
    filtered.extend(filter_time(shell_stdin,since_dt,until_dt))

    if ooo and not filtered and not ordered_cmds:
        fp,c,mt=ooo[0]
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)
        sys.exit(1)
    for fp,c,mt in ooo:
        print_o_range(fp,c,mt,since_str,until_str,since_dt,until_dt)

    def skey(e):
        lt=e.get('log_time')
        if lt:
            return (lt, e.get('log_line',0))
        else:
            return (datetime.datetime.min.replace(tzinfo=timezone.utc), e.get('log_line',0))
    filtered.sort(key=skey)

    outs, cmd_errs, last_res, last_cols, enabled_filters, cursor = exec_cmds(filtered, ordered_cmds)

    for em in cmd_errs:
        sys.stderr.write(em)
        if not em.endswith("\n"):
            sys.stderr.write("\n")
    for out in outs:
        sys.stdout.write(out)
        if not out.endswith("\n"):
            sys.stdout.write("\n")

    if not outs and last_res is not None and "-q" not in args:
        if last_res and last_cols:
            widths={}
            for col in last_cols:
                ml=len(col)
                for row in last_res:
                    v=row.get(col)
                    s=str(v) if v is not None else "<NULL>"
                    if len(s)>ml:
                        ml=len(s)
                widths[col]=ml
            header=" ".join([col.ljust(widths[col]) for col in last_cols])
            sys.stdout.write(header+"\n")
            for row in last_res:
                parts=[]
                for col in last_cols:
                    v=row.get(col)
                    s=str(v) if v is not None else "<NULL>"
                    parts.append(s.ljust(widths[col]))
                sys.stdout.write(" ".join(parts)+"\n")

    if not outs and last_res is None and "-q" not in args:
        in_pats=[p for t,p in enabled_filters if t=="in"]
        out_pats=[p for t,p in enabled_filters if t=="out"]
        def passes_raw(b):
            if in_pats:
                if not any(pp.lower() in b.lower() for pp in in_pats): return False
                if any(pp.lower() in b.lower() for pp in out_pats): return False
                return True
            else:
                return not any(pp.lower() in b.lower() for pp in out_pats)
        for ii,e in enumerate(filtered):
            if ii < cursor: continue
            body=e.get('log_body','')
            if not passes_raw(body): continue
            sys.stdout.write(e.get('raw','')+"\n")

    sys.exit(0)

if __name__=="__main__":
    main()
